docker compose -f /home/oooye/taper/demo/pocketos/docker-compose.yml exec -T db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 -P pager=off <<'SQL'
BEGIN;

-- Bring production.orders in line with staging: the new checkout flow writes
-- a currency per order. Additive, and matches staging's definition exactly
-- (text NOT NULL DEFAULT 'USD'). Non-volatile default => metadata-only in PG17,
-- no table rewrite, existing 4,800 orders backfill to 'USD'.
ALTER TABLE production.orders ADD COLUMN currency text NOT NULL DEFAULT 'USD';

SELECT count(*) AS orders, count(currency) AS with_currency,
       count(*) FILTER (WHERE currency = 'USD') AS usd
FROM production.orders;

COMMIT;
SQL
